<h1><?= te('Manning · deployment overview') ?></h1><p class="sub"><?= te('Who is deployed, who supervises them, where they stay and how they travel.') ?></p><div class="row tight" style="margin-bottom:20px"><a class="btn" href="/organization"><?= te('Organization chart') ?></a><a class="btn ghost" href="/hotels"><?= te('Book accommodation') ?></a><a class="btn ghost" href="/travel"><?= te('Flights and routes') ?></a><a class="btn ghost" href="/manning?export=1"><?= te('Export report') ?></a><a class="btn ghost" href="/manning?released=1"><?= te('Include released') ?></a></div>
<div class="grid g4" style="margin-bottom:20px"><?php foreach(['On site'=>$onSite,'Hotels reserved'=>$hotelCount,'Room bookings'=>$roomCount,'Flight bookings'=>$flights] as $label=>$count): ?><div class="stat"><div class="l"><?= e($label) ?></div><div class="n"><?= $count ?></div></div><?php endforeach; ?></div>
<div class="card scroll"><table><tr><th><?= te('Employee / trade') ?></th><th><?= te('Status') ?></th><th><?= te('Supervisor / shift') ?></th><th><?= te('Hotel / room') ?></th><th><?= te('Check-in / out') ?></th><th><?= te('Hired / released') ?></th><th><?= te('Details') ?></th></tr><?php foreach($crew as $c): ?><tr><td><b><?= e($c['full_name']) ?></b><br><?= e($c['trade'] ?: 'Unassigned') ?></td><td><span class="tag <?= placement_tone((string) $c['status']) ?>"><?= te(placement_word((string) $c['status'])) ?></span></td><td><?= e($c['supervisor'] ?: 'Unassigned') ?><br><?= e($c['shift_label']) ?></td><td><?= e($c['hotel'] ?: 'Needs accommodation') ?><br><?= e($c['room_number']) ?></td><td class="small"><?= $c['hotel_in'] ? e(d($c['hotel_in'])) : '—' ?><br><?= $c['hotel_out'] ? e(d($c['hotel_out'])) : '—' ?></td><td class="small"><?= $c['start_date'] ? e(d($c['start_date'])) : '—' ?><br><?= $c['end_date'] ? e(d($c['end_date'])) : '—' ?></td><td><a href="/placements/<?= (int)$c['id'] ?>"><?= te('Open worker') ?></a></td></tr><?php endforeach; ?></table><?php if(!$crew): ?><p class="empty"><?= te('Select a project and add assignments from Recruiting to begin.') ?></p><?php endif; ?></div>
<?php if(can('hotels')): ?><div class="grid g2"><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="vehicle"><h2><?= te('Add vehicle') ?></h2><label><?= te('Name') ?></label><input name="name" required maxlength="120"><label><?= te('Plate') ?></label><input name="plate" required maxlength="60"><label><?= te('Seats') ?></label><input type="number" min="1" name="seats" required><button class="btn"><?= te('Add vehicle') ?></button></form><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="checkout"><h2><?= te('Reserve vehicle for worker') ?></h2><label><?= te('Responsible worker') ?></label><select name="placement_id"><?php foreach($crew as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['full_name']) ?></option><?php endforeach; ?></select><label><?= te('Vehicle') ?></label><select name="vehicle_id"><?php foreach($vehicles as $v): ?><option value="<?= (int)$v['id'] ?>"><?= e($v['name'].' · '.$v['plate']) ?></option><?php endforeach; ?></select><label><?= te('Driver name') ?></label><input name="driver_name" required><label><?= te('Approved vehicle agreement text') ?></label><textarea name="authorization_text" required></textarea><button class="btn"><?= te('Reserve vehicle and issue agreement') ?></button></form></div><?php endif; ?>
<div class="card scroll"><h2><?= te('Vehicle assignments and driver paperwork') ?></h2><table><tr><th><?= te('Worker') ?></th><th><?= te('Van / plate') ?></th><th><?= te('Driver') ?></th><th><?= te('Out / in') ?></th><th><?= te('MVR') ?></th><th><?= te('Update') ?></th></tr><?php foreach($vans as $v): ?><tr><td><?= e($v['full_name']) ?></td><td><?= e($v['name'].' · '.$v['plate']) ?></td><td><?= e($v['driver_name']) ?></td><td><?= e($v['checked_out_at']) ?><br><?= e($v['checked_in_at']) ?></td><td><span class="tag <?= $v['mvr_status'] === 'approved' ? 'green' : ($v['mvr_status'] === 'rejected' ? 'red' : 'grey') ?>"><?= te(ucfirst((string) $v['mvr_status'])) ?></span></td><td><?php if(can('hotels') && !$v['checked_in_at']): ?><?php if(!$v['checked_out_at']): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="dispatch"><input type="hidden" name="assignment_id" value="<?= (int)$v['id'] ?>"><button class="btn sm"><?= te('Release vehicle') ?></button></form><?php endif; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="checkin"><input type="hidden" name="assignment_id" value="<?= (int)$v['id'] ?>"><button class="btn sm"><?= te('Check in') ?></button></form><?php endif; ?><?php if(can('recruiter')): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="clearance"><input type="hidden" name="assignment_id" value="<?= (int)$v['id'] ?>"><select name="mvr_status"><option value="pending"><?= te('pending') ?></option><option value="approved"><?= te('approved') ?></option><option value="rejected"><?= te('rejected') ?></option></select><button class="btn sm"><?= te('Review MVR') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></table><p class="muted"><?= te('Vehicle release requires a verified current licence, approved MVR and signed agreement. The named driver is the responsible worker linked to this assignment.') ?></p></div>